import java.util.HashMap;
import java.util.Map;

class LRUCache {
    private static class Entry {
        int key;
        int value;
        Entry previous;
        Entry next;
        Entry(int key, int value) { this.key = key; this.value = value; }
    }

    private final int capacity;
    private final Map<Integer, Entry> entries = new HashMap<>();
    private final Entry front = new Entry(0, 0);
    private final Entry back = new Entry(0, 0);

    public LRUCache(int capacity) {
        this.capacity = capacity;
        front.next = back;
        back.previous = front;
    }

    public int get(int key) {
        Entry entry = entries.get(key);
        if (entry == null) return -1;
        moveToFront(entry);
        return entry.value;
    }

    public void put(int key, int value) {
        Entry entry = entries.get(key);
        if (entry != null) {
            entry.value = value;
            moveToFront(entry);
            return;
        }
        entry = new Entry(key, value);
        entries.put(key, entry);
        attachAfterFront(entry);
        if (entries.size() > capacity) {
            Entry leastRecent = back.previous;
            remove(leastRecent);
            entries.remove(leastRecent.key);
        }
    }

    private void moveToFront(Entry entry) {
        remove(entry);
        attachAfterFront(entry);
    }

    private void remove(Entry entry) {
        entry.previous.next = entry.next;
        entry.next.previous = entry.previous;
    }

    private void attachAfterFront(Entry entry) {
        entry.next = front.next;
        entry.previous = front;
        front.next.previous = entry;
        front.next = entry;
    }
}
